// The TypeScript port must agree with the Python reference implementation. golden.json holds answers
// generated by the Python code (see backend/); deterministic quantities must match exactly, sampled
// ones (equities) within sampling noise, because the two sides use different random generators.

import { describe, expect, it } from 'vitest';
import { boardEquity } from './charts';
import { evaluate } from './evaluate';
import golden from './golden.json';
import { parseCompact } from './cards';
import { ORDER, chartFor } from './ranges';

describe('against the Python reference', () => {
	it('evaluates 600+ hands to the same score, category, name and five cards', () => {
		for (const h of golden.evaluate) {
			const v = evaluate(h.cards);
			expect(v.score, h.cards.join(',')).toBe(h.score);
			expect(v.category).toBe(h.category);
			expect(v.name).toBe(h.name);
			expect([...v.cards].sort((a, b) => a - b)).toEqual(h.best);
		}
	});

	it('orders the 169 hands the same way', () => {
		expect([...ORDER]).toEqual(golden.order);
	});

	it('builds the same opening range for every seat at every table size', () => {
		for (const [n, seats] of Object.entries(golden.seat_ranges)) {
			const mine = chartFor(Number(n));
			expect(mine.map((s) => s.name)).toEqual(seats.map((s) => s.name));
			seats.forEach((seat, i) => {
				const r = mine[i].range;
				expect([...r.hands].sort(), `${n} players, ${seat.name}`).toEqual(seat.hands);
				expect(r.source).toBe(seat.source);
				expect(r.pct).toBeCloseTo(seat.pct, 9);
				expect(mine[i].behind).toBe(seat.behind);
			});
		}
	});

	it('answers board-equity questions like the reference', () => {
		for (const ref of golden.boards) {
			const q = ref.query as Record<string, string | number | undefined>;
			const result = boardEquity({
				pot: q.pot as 'srp' | '3bet' | '4bet',
				opener: q.opener as string,
				other: q.other as string,
				side: q.side as 'opener' | 'other',
				board: parseCompact(q.board as string),
				hole: q.hole ? parseCompact(q.hole as string) : null,
				bet: (q.bet as number | undefined) ?? null,
				view: 'mine'
			});
			const label = JSON.stringify(q);
			// Deterministic: which range, how many combos, the street and texture.
			expect(result.street, label).toBe(ref.street);
			expect(result.texture, label).toBe(ref.texture);
			expect(result.aggressor, label).toBe(ref.aggressor);
			expect(result.unknown.my_combos, label).toBe(ref.my_combos);
			expect(result.unknown.their_combos, label).toBe(ref.their_combos);
			expect(Object.keys(result.unknown.grid).sort(), label).toEqual(ref.grid_classes);
			expect(result.plan.role, label).toBe(ref.plan.role);
			expect(result.facing, label).toEqual(ref.facing);
			// Sampled: within the noise of a few hundred scenarios.
			expect(Math.abs(result.unknown.my_range_eq - ref.my_range_eq), label).toBeLessThan(0.045);
			expect(result.unknown.my_range_eq + result.unknown.their_range_eq).toBeCloseTo(1, 9);
			expect(Math.abs(result.plan.bet_frequency - ref.plan.bet_frequency), label).toBeLessThan(0.2);
			if (ref.grid_AA !== null && result.unknown.grid.AA !== undefined) {
				expect(Math.abs(result.unknown.grid.AA - ref.grid_AA), label).toBeLessThan(0.08);
			}
			if (ref.known) {
				const known = result.known!;
				expect(known.hand, label).toBe(ref.known.hand);
				expect(known.made_hand, label).toBe(ref.known.made_hand);
				expect(known.has_made_hand, label).toBe(ref.known.has_made_hand);
				expect(Math.abs(known.equity - ref.known.equity), label).toBeLessThan(0.07);
				expect(Math.abs(known.rank - ref.known.rank), label).toBeLessThan(0.2);
			} else {
				expect(result.known, label).toBeNull();
			}
		}
	});
});
